]=449,["skillLv6"]=959,["skillLv7"]=959,["skillLv8"]=959,["skillLv9"]=959,["str"]=21,["textEscape"]=[[呵呵，怎么不打了？;人家刚认真起来就不打了，真扫兴。;就没一个能打的吗？;别走啊，妾身可是诚心来讨教的，嘻嘻。;你夹着尾巴逃跑的样子真好笑，咯咯咯。;难道又是一个欺世盗名之辈？哎，真让我失望。;妾身有这么可怕吗，放心好了，我不下死手就是了，呵呵。;奴家又不是什么邪派女魔头，有这么可怕吗……]],["textLose"]=[[是妾身输了……呜呜呜。;小女子甘拜下风。;是妾身学艺不精，告辞。;青山不改，绿水长流，后会有期。;阁下武艺高强，奴家真是不自量力，失礼了。;果然不虚此行，受教了。;可恶，我还会回来的。;江湖之大，果然能人辈出啊。;小女子方才多有得罪，有眼不识泰山，失礼了。]],["textMoren"]=[[小女子愿意以平生所学向阁下讨教几招，望不吝赐教。;听闻阁下武艺高强，请赐教。;听闻此间主人武艺高强，特前来讨教讨教。;听闻此间主人也是江湖中人，奴家斗胆，愿领教领教。;奴家会点三脚猫功夫，想找个人打打架，希望不要嫌弃哟，咯咯咯。;妾身在江湖上也小有名气，非弱质女流。请赐教！;奴家别无所求，但求以武会友、结识江湖同道，望成全。]],["textWin"]=[[承让承让。;呵呵，是妾身赢了。;阁下好俊的身手，但还是奴家技高一筹，呵呵。;是个不错的对手，让妾身也大开眼界了呢。;连一个能打的都没有吗？;真是言过其实，让人好生失望。;功夫都是师娘教的吧？这么不经打，嘻嘻。;承让承让，与君交手，奴家也是受益良多。]],["weapon"]=[[item07_13]],["zhaojia"]=[[jibenzhaojia]]},["2605"]={["activeZhao1"]=[[sijisanhua3]],["activeZhao2"]=[[sanhuahuasanqing5]],["age"]=27,["anqi"]=[[jibenanqi]],["bianfa"]=[[jibenbianfa]],["con"]=20,["daofa"]=[[jibendaofa]],["dex"]=18,["dsc"]=[[他是一副道士的打扮，也不知道是不是真的方外之人。]],["exp"]=45914660,["groupID"]=2,["gunfa"]=[[jibengunfa]],["id"]=2605,["isShowEquips"]=1,["jiali"]=152,["jianfa"]=[[jibenjianfa]],["looks"]=22,["lv"]=786,["maxlevel"]=799,["minlevel"]=700,["neigong"]=[[jibenneigong]],["neili"]=50467,["qi"]=11672,["qingong"]=[[jibenqinggong]],["quanjiao1"]=[[sanhuajudingzhang]],["release_rule1"]=[[moban8]],["release_rule2"]=[[moban3]],["sex"]=[[男]],["shuangchi"]=[[jibenshuangchi]],["skill1"]=[[sanhuajudingzhang]],["skill10"]=[[jibenshuangchi]],["skill2"]=[[jibenzhaojia]],["skill3"]=[[jibenqinggong]],["skill4"]=[[jibenneigong]],["skill5"]=[[jibenjianfa]],["skill6"]=[[jibendaofa]],["skill7"]=[[jibengunfa]],["skill8"]=[[jibenanqi]],["skill9"]=[[jibenbianfa]],["skillLv1"]=449,["skillLv10"]=959,["skillLv2"]=959,["skillLv3"]=959,["skillLv4"]=959,["skillLv5"]=959,["skillLv6"]=959,["skillLv7"]=959,["skillLv8"]=959,["skillLv9"]=959,["str"]=18,["textEscape"]=[[呵呵，怎么不打了？;不过瘾不过瘾，我刚认真起来就不打了。;就没一个能打的吗？;别走啊，在下可是诚心来讨教的。;无敌真寂寞，呵呵。;难道又是一个欺世盗名之辈？哎，真让我失望。;想遇到一个可以让我痛快打上一场的人。]]